import itertools

def count_triangles(n, edges, color_map):
    """
    Counts monochromatic triangles for a given coloring.
    Vertices are 0 to n-1. Edges are stored as tuples (u, v).
    color_map[(u, v)] gives the color (0 or 1) of the edge.
    """
    triangles = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                e_ij = tuple(sorted((i, j)))
                e_jk = tuple(sorted((j, k)))
                e_ki = tuple(sorted((k, i)))

                # Check if all three edges exist (should always be true for K_n)
                if e_ij in color_map and e_jk in color_map and e_ki in color_map:
                    c_ij = color_map[e_ij]
                    c_jk = color_map[e_jk]
                    c_ki = color_map[e_ki]

                    # Check if all three edges have the same color
                    if c_ij == c_jk and c_jk == c_ki:
                        triangles += 1
    return triangles

# Test n=5 (Known to have a counterexample, C_5 coloring)
n5 = 5
# Edges of K5
edges_5 = list(itertools.combinations(range(n5), 2))
# Coloring corresponding to C5 (0-1-2-3-4-0)
color_map_5 = {}
for i, j in edges_5:
    if abs(i - j) == 1 or abs(i - j) == 4:
        # Edges on the cycle (Color 0)
        color_map_5[(i, j)] = 0
    else:
        # Diagonals (Color 1)
        color_map_5[(i, j)] = 1

tri_count_5 = count_triangles(n5, edges_5, color_map_5)
print(f"N=5 (C5 coloring): Monochromatic triangles = {tri_count_5}")

# Test n=6 (Checking for a coloring that yields exactly 1 triangle, if one exists)
# The known minimal coloring that achieves R(3, 3) = 6 guarantees at least 1, but might have more.
# Let's test the construction $K_3 \cup K_3$ red, $K_{3,3}$ blue, which yields 2 triangles.
n6 = 6
edges_6 = list(itertools.combinations(range(n6), 2))
color_map_6 = {}

# Partition vertices into {0, 1, 2} and {3, 4, 5}
V1 = {0, 1, 2}
V2 = {3, 4, 5}

# Color within partitions Red (Color 0)
for u, v in itertools.combinations(V1, 2):
    color_map_6[(u, v)] = 0
for u, v in itertools.combinations(V2, 2):
    color_map_6[(u, v)] = 0

# Color between partitions Blue (Color 1)
for u in V1:
    for v in V2:
        color_map_6[(u, v)] = 1

tri_count_6 = count_triangles(n6, edges_6, color_map_6)
print(f"N=6 (K3+K3 red, K3,3 blue): Monochromatic triangles = {tri_count_6}")
